param(
    [string]$WorkspaceRoot = (Split-Path -Parent $PSScriptRoot),
    [string]$WolvenKitRoot = 'C:\Users\Ayong\Documents\WolvenKit-8.20.0'
)
Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
. (Join-Path $PSScriptRoot 'build_phase2a.ps1') -WorkspaceRoot $WorkspaceRoot -WolvenKitRoot $WolvenKitRoot -HelpersOnly

# Derive this prompt experiment from the already reviewed V-only mirror action.
# That source is generated by build_b0_h10_vonly_mirror.ps1; keep the two probes
# separate so the installed manual experiment is not modified by this build.
$actionScenePath = Join-Path $WorkspaceRoot 'archive\b0_h10_vonly_mirror\source\towercontinued\b0_h10_vonly_mirror\h10_v_mirror.scene'
$manualGatePath = Join-Path $WorkspaceRoot 'archive\b0_h10_vonly_mirror\source\towercontinued\b0_h10_vonly_mirror\manual_gate.questphase'
$sceneDepot = 'towercontinued\b0_h10_mirror_prompt\mirror_prompt.scene'
$gateDepot = 'towercontinued\b0_h10_mirror_prompt\prompt_gate.questphase'
$archiveName = 'TowerContinued_B0_H10_MirrorPrompt.archive'
$src = Join-Path $WorkspaceRoot 'archive\b0_h10_mirror_prompt\source'
$out = Join-Path $WorkspaceRoot 'build\B0_H10_MirrorPrompt'
$val = Join-Path $WorkspaceRoot 'research\b0_h10_mirror_prompt\validation'
$inputs = @($actionScenePath, $manualGatePath)
foreach ($path in $inputs) { if (-not (Test-Path -LiteralPath $path -PathType Leaf)) { throw "Missing reviewed source: $path" } }
$inputHashes = @{}
foreach ($path in $inputs) { $inputHashes[$path] = (Get-FileHash -LiteralPath $path -Algorithm SHA256).Hash }
New-Item -ItemType Directory -Force -Path $src,$out,$val | Out-Null

$scene = Read-Cr2wFile $actionScenePath
$nodes = $scene.RootChunk.SceneGraph.Chunk.Graph
function SceneNode([int]$id) {
    $matches = @($nodes | Where-Object { $_.Chunk.NodeId.Id.ToString() -eq "$id" })
    if ($matches.Count -ne 1) { throw "Scene node $id is not unique" }
    return $matches[0].Chunk
}
function EditDest([int]$id,[int]$socket,[int]$from,[int]$to) {
    $destinations = (SceneNode $id).OutputSockets[$socket].Destinations
    $matches = @($destinations | Where-Object { $_.NodeId.Id.ToString() -eq "$from" })
    if ($matches.Count -ne 1) { throw "Expected one scene edge $id/$socket->$from" }
    $matches[0].NodeId.Id = [WolvenKit.RED4.Types.CUInt32]::op_Implicit([uint32]$to)
}
# Arm the same mirror-only world choice hub used by vanilla after Leave. This
# is a hypothesis that a manual scene entry can show the physical prompt.
# Add only the H10 outside-trigger condition, following a one-site mirror
# precedent. Do not arm vanilla's incoming-call/apartment-off monitor: it can
# terminate an active mirror action without running its normal cleanup.
EditDest 434 0 220 509
$monitorEdge = (SceneNode 434).OutputSockets[0].Destinations[0].DeepCopy()
$monitorEdge.NodeId.Id = [WolvenKit.RED4.Types.CUInt32]::op_Implicit([uint32]1112)
(SceneNode 434).OutputSockets[0].Destinations.Add($monitorEdge)
# The generic H10 outside tail removes shower/sit/sleep phone restrictions.
# This mirror-only scene should remove only its own source if it exits idle.
EditDest 1112 0 1109 1104
# On ordinary Leave, rearm the world choice after vanilla's five-second
# cleanup delay. The earlier V-only probe ended the scene here.
EditDest 242 0 2 509

$scenePath = Join-Path $src $sceneDepot
Write-Cr2wFile $scene $scenePath
$sceneCheck = Read-Cr2wFile $scenePath
Export-Cr2wJson $sceneCheck (Join-Path $val 'mirror_prompt.scene.json')

$manualGate = Read-Cr2wFile $manualGatePath
$manualGraph = $manualGate.RootChunk.Graph.Chunk
$sceneNode = Get-QuestNode $manualGraph 7
$resourcePath = [WolvenKit.RED4.Types.ResourcePath]::op_Implicit($sceneDepot)
$sceneNode.SceneFile = [Activator]::CreateInstance($sceneNode.GetType().GetProperty('SceneFile').PropertyType,[object[]]@($resourcePath))
$gatePath = Join-Path $src $gateDepot
Write-Cr2wFile $manualGate $gatePath
$gateCheck = Read-Cr2wFile $gatePath
Export-Cr2wJson $gateCheck (Join-Path $val 'prompt_gate.questphase.json')

foreach ($path in $inputs) {
    if ((Get-FileHash -LiteralPath $path -Algorithm SHA256).Hash -ne $inputHashes[$path]) { throw "Reviewed source changed during build: $path" }
}
$allowed = @($gateDepot,$sceneDepot) | Sort-Object
$actual = @(Get-ChildItem -LiteralPath $src -File -Recurse | ForEach-Object { [IO.Path]::GetRelativePath($src,$_.FullName) } | Sort-Object)
if (@(Compare-Object $allowed $actual).Count) { throw 'Unexpected source file in prompt archive' }
$hashService = [WolvenKit.Common.Services.HashService]::new(); $hashService.Load()
$stream = [IO.File]::Create((Join-Path $out $archiveName))
try {
    $writer = [WolvenKit.RED4.Archive.IO.ArchiveWriter]::new($hashService,[WolvenKit.SerilogWrapper]::new())
    if (-not $writer.WriteArchive([IO.DirectoryInfo]::new($src),$stream)) { throw 'Archive write failed' }
} finally { $stream.Dispose() }
$reader = [WolvenKit.RED4.Archive.IO.ArchiveReader]::new(); $archive = $null
if ($reader.ReadArchive((Join-Path $out $archiveName),$hashService,[ref]$archive).ToString() -ne 'NoError') { throw 'Archive did not reopen' }
$packed = @($archive.Files.Values | ForEach-Object { $_.Name } | Sort-Object)
if (@(Compare-Object $allowed $packed).Count) { throw 'Archive manifest mismatch' }
foreach ($entry in $archive.Files.Values) {
    $memory = [IO.MemoryStream]::new()
    try {
        $entry.Extract($memory)
        $hash = [Convert]::ToHexString([Security.Cryptography.SHA256]::HashData($memory.ToArray()))
        if ($hash -ne (Get-FileHash -LiteralPath (Join-Path $src $entry.Name) -Algorithm SHA256).Hash) { throw "Packed bytes differ: $($entry.Name)" }
    } finally { $memory.Dispose() }
}
$manifest = [ordered]@{
    status = 'STATIC_CANDIDATE_DO_NOT_INSTALL'
    blocker = 'Outside-only scene end still bypasses active mirror workspot/device/proxy/variant cleanup on forced exit; Default INT and unload cleanup are unvalidated'
    additional_preflight = 'Remove the prior manual mirror experiment; use a disposable restored-H10 save'
    archive = $archiveName
    sha256 = (Get-FileHash -LiteralPath (Join-Path $out $archiveName) -Algorithm SHA256).Hash
    resources = $packed
    source_hashes = $inputHashes
    vanilla_replacements = @()
    scene_entry = 'in_mirror via manual request'
    scene_choice = 'mirror only'
    manual_fact = 'PTFRB0H10M_Request'
}
[IO.File]::WriteAllText((Join-Path $val 'build_manifest.json'),($manifest | ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false))
$manifest | ConvertTo-Json -Depth 8
